//! A hypoid or spiral bevel pair generated by one crown, as a gear designer lays it out: the
//! pitch cones and the tooth trace through the mean point M on the pitch plane P, then each
//! member cut by a generating crown, a face mill's: its blank less the crown rolled through it
//! at every tooth (the pinion by the crown's tooth, the gear by the space beside it).
//!
//! The layout is `hypoid.sv`'s:
//!
//! - **The gear's cone.** Its apex O on P, M on P's x axis; the right triangle O–M–F square to
//!   P on O → M, F (the foot of M on the gear's axis) below P, its legs the two members' pitch
//!   radii at M in proportion to their teeth (`z₁ m / 2`, `z₂ m / 2`), so the mean cone distance
//!   is R = m √(z₁² + z₂²) / 2 and the gear's pitch angle `asin(z₂ / √(z₁² + z₂²))`. The crown's
//!   axis stands up from O, square to P; it has √(z₁² + z₂²) teeth.
//! - **The tooth trace.** The circle about the cutter's centre C through M, its normal C → M at
//!   90° less the spiral angle to O → M. The normal module is the module seen square to it,
//!   `m cos β`.
//! - **The pinion's cone,** solved against the gear's: its apex A on P, on the offset's side,
//!   behind M on the line A → M (the pinion's pitch line); its axis square to P's level line
//!   across A → M, rising from A, at the shaft angle to the gear's and the offset from it. The
//!   pinion's pitch radius at M is that of a virtual bevel pinion whose apex V is where A → M
//!   crosses the line from O along the trace's normal, at the bevel pinion's pitch angle
//!   (90° less the gear's): `|MA| sin γ = |MV| cos δ₂`. With the cutter's centre on the offset's
//!   side, `|MV| cos(β + ε) = R cos β` (ε the angle between O → M and A → M): the pinion's spiral
//!   angle is the gear's and ε. No offset is a bevel pair (A and V are O).
//! - **The face mill.** The crown's tooth is a quarter crown pitch either side of M on the mean
//!   pitch circle; the circles about C through those two points give its inner and outer blade
//!   radii on P. The blades are cones about the cutter's axis (square to P through C) at the
//!   pressure angle plus and less the pressure shift, the inner opening up the axis, the outer
//!   down it. The crown's tooth stands from two normal modules under P to its tip a dedendum
//!   over it; its space is the tooth's mate, from a dedendum under P to two modules over it.
//!
//! Frame: P is the x–y plane, O the origin, M on +x, the crown's axis +z; the gear is under P,
//! the pinion over it, the offset toward +y.

use super::{Vec3, add, cross, dot, norm, scale, sub};
use std::f64::consts::PI;

/// A pair as a designer states it. Angles in radians, lengths in mm.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Design {
    pub pinion_teeth: f64,
    pub gear_teeth: f64,
    /// The module at the mean point M.
    pub module: f64,
    pub shaft_angle: f64,
    /// The common perpendicular's length between the two axes: 0 for a bevel pair.
    pub offset: f64,
    /// The crown's spiral angle at M (the gear's).
    pub spiral: f64,
    pub cutter_radius: f64,
    pub pressure: f64,
    /// Steepens the inner blade and flattens the outer.
    pub pressure_shift: f64,
}

/// The layout the design solves to.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Layout {
    /// The crown's teeth and the mean cone distance.
    pub crown_teeth: f64,
    pub mean_cone: f64,
    /// The normal module, and the depths in it: the addendum (each member's), the dedendum,
    /// and the crown tooth's base under P.
    pub normal_module: f64,
    pub addendum: f64,
    pub dedendum: f64,
    pub base: f64,
    /// The mean point.
    pub m: Vec3,
    /// The gear: its apex O (the origin), its axis from it toward the gear's body, its pitch
    /// angle.
    pub gear_axis: Vec3,
    pub gear_pitch: f64,
    /// The pinion: its apex A, its axis from it toward the pinion's body, its pitch angle, its
    /// cone distance |AM|, and the angle ε between O → M and A → M.
    pub pinion_apex: Vec3,
    pub pinion_axis: Vec3,
    pub pinion_pitch: f64,
    pub pinion_cone: f64,
    pub offset_angle: f64,
    /// The cutter's centre on P, and its blades: their radii on P and the tangents of their
    /// half angles (the inner blade's opening up the cutter's axis, the outer's down it).
    pub cutter: Vec3,
    pub inner_radius: f64,
    pub outer_radius: f64,
    pub inner_tan: f64,
    pub outer_tan: f64,
}

impl Layout {
    /// The pinion's pitch radius at M.
    pub fn pinion_radius(&self) -> f64 {
        self.pinion_cone * self.pinion_pitch.sin()
    }
}

/// The layout, or why there is none.
pub fn layout(d: &Design) -> Result<Layout, &'static str> {
    let (z1, z2, m) = (d.pinion_teeth, d.gear_teeth, d.module);
    let crown = z1.hypot(z2);
    let r = m * crown / 2.0;
    let gear_pitch = (z2 / crown).asin();
    let bevel_pinion = PI / 2.0 - gear_pitch;
    let g = [gear_pitch.cos(), 0.0, -gear_pitch.sin()];
    let mp = [r, 0.0, 0.0];
    // The trace's normal C → M, the cutter's centre on the offset's side.
    let a = -(PI / 2.0 - d.spiral);
    let n = [a.cos(), a.sin(), 0.0];
    let c = sub(mp, scale(n, d.cutter_radius));
    // The pinion's cone from (ε, L = |AM|, γ): A = M − L u, u = (cos ε, −sin ε, 0), its axis
    // cos γ u + sin γ z.
    let parts = |x: [f64; 3]| {
        let [eps, l, gam] = x;
        let u = [eps.cos(), -eps.sin(), 0.0];
        let apex = sub(mp, scale(u, l));
        let axis = add(scale(u, gam.cos()), [0.0, 0.0, gam.sin()]);
        (u, apex, axis)
    };
    let miss = |x: [f64; 3]| -> [f64; 3] {
        let [_, l, gam] = x;
        let (u, apex, axis) = parts(x);
        // (The pinion's axis × the gear's points to +y, the offset's side.)
        let across = cross(axis, g);
        let apart = dot(apex, across) / norm(across);
        // V: where A → M crosses the line from O along n (O + q n = M − |MV| u).
        let mv = (n[0] * mp[1] - n[1] * mp[0]) / (n[0] * u[1] - n[1] * u[0]);
        [
            dot(g, axis) - d.shaft_angle.cos(),
            apart - d.offset,
            mv * bevel_pinion.sin() - l * gam.sin(),
        ]
    };
    // Newton's method from the bevel pair's cone, its offset taken on in steps.
    let mut x = [0.0, r, bevel_pinion];
    let steps = 8;
    for k in 1..=steps {
        let target = Design {
            offset: d.offset * k as f64 / steps as f64,
            ..*d
        };
        let f = |x: [f64; 3]| {
            let mut v = miss(x);
            v[1] += d.offset - target.offset;
            v
        };
        let mut done = false;
        for _ in 0..50 {
            let f0 = f(x);
            if f0.iter().all(|v| v.abs() < 1e-12 * r.max(1.0)) {
                done = true;
                break;
            }
            let mut jac = [[0.0; 3]; 3];
            for j in 0..3 {
                let h = 1e-7 * x[j].abs().max(1.0);
                let mut xp = x;
                xp[j] += h;
                let fp = f(xp);
                for i in 0..3 {
                    jac[i][j] = (fp[i] - f0[i]) / h;
                }
            }
            let dx = solve3(jac, f0).ok_or("The pinion's cone can't be laid out")?;
            for j in 0..3 {
                x[j] -= dx[j];
            }
        }
        if !done && !miss(x).iter().all(|v| v.abs() < 1e-9 * r.max(1.0)) && k == steps {
            return Err("The pinion's cone can't be laid out");
        }
    }
    let [eps, l, gam] = x;
    if !(l > 0.0 && gam > 0.0 && gam < PI / 2.0 && x.iter().all(|v| v.is_finite())) {
        return Err("The pinion's cone can't be laid out");
    }
    let (_, apex, axis) = parts(x);
    if apex[1] < -1e-9 {
        return Err("The pinion's cone can't be laid out");
    }
    // The face mill's blades.
    let phi = PI * m / 4.0 / r;
    let ahead = [r * phi.cos(), r * phi.sin(), 0.0];
    let behind = [r * phi.cos(), -r * phi.sin(), 0.0];
    let (inner_radius, outer_radius) = (norm(sub(c, ahead)), norm(sub(c, behind)));
    let mn = m * d.spiral.cos();
    let (inner_tan, outer_tan) = (
        (d.pressure + d.pressure_shift).tan(),
        (d.pressure - d.pressure_shift).tan(),
    );
    if !(inner_tan > 0.0 && outer_tan > 0.0 && inner_radius < outer_radius) {
        return Err("The face mill's blades don't make a tooth: lower the pressure shift");
    }
    Ok(Layout {
        crown_teeth: crown,
        mean_cone: r,
        normal_module: mn,
        addendum: mn,
        dedendum: 1.25 * mn,
        base: 2.0 * mn,
        m: mp,
        gear_axis: g,
        gear_pitch,
        pinion_apex: apex,
        pinion_axis: axis,
        pinion_pitch: gam,
        pinion_cone: l,
        offset_angle: eps,
        cutter: c,
        inner_radius,
        outer_radius,
        inner_tan,
        outer_tan,
    })
}

/// Where the gear's axis comes nearest the pinion's: the foot on the gear's axis of their
/// common perpendicular.
pub fn gear_foot(l: &Layout) -> Vec3 {
    let (g, p) = (l.gear_axis, l.pinion_axis);
    let w = l.pinion_apex;
    let b = dot(g, p);
    let t = (dot(g, w) - b * dot(p, w)) / (1.0 - b * b);
    scale(g, t)
}

/// The common perpendicular from the gear's axis to the pinion's (its length the offset).
pub fn perpendicular(l: &Layout) -> Vec3 {
    let (g, p) = (l.gear_axis, l.pinion_axis);
    let w = l.pinion_apex;
    let b = dot(g, p);
    let t = (b * dot(g, w) - dot(p, w)) / (1.0 - b * b);
    sub(add(w, scale(p, t)), gear_foot(l))
}

/// The crown's roll each way while it cuts a member (radians): past where its tooth or space
/// leaves the blank at either end of the face.
const ROLL: f64 = 45.0 * PI / 180.0;

/// One member generated, in the pair's frame (P the x–y plane): its blank, the crown's tooth
/// (the pinion's tool) or space (the gear's), the crown's roll and the member's, and its teeth.
/// `grow`: each crown flank moved out this far (a quarter of the normal backlash: the envelope
/// of an offset is the offset of the envelope); `relief`: the tips' toe and heel edges
/// chamfered this far each way.
pub(super) fn member(
    d: &Design,
    l: &Layout,
    gear: bool,
    grow: f64,
    relief: f64,
) -> super::Generated {
    use super::{Frame, Generated, Region2, Revolved, Seg};
    let r = l.mean_cone;
    let width = 0.2 * r;
    let back = 4.0 * l.normal_module;
    let (apex, axis, pitch, cone, teeth) = if gear {
        ([0.0; 3], l.gear_axis, l.gear_pitch, r, d.gear_teeth)
    } else {
        (
            l.pinion_apex,
            l.pinion_axis,
            l.pinion_pitch,
            l.pinion_cone,
            d.pinion_teeth,
        )
    };
    // A frame whose y is `axis`, its x toward `toward`, at `origin`.
    let frame = |origin: Vec3, axis: Vec3, toward: Vec3| {
        let x = super::unit(sub(toward, scale(axis, dot(toward, axis))));
        Frame {
            origin,
            x,
            normal: cross(x, axis),
        }
    };
    // The blank in (radius, height along the axis from the apex): between the pitch cone
    // shrunk by `back` and grown by the addendum, between the spheres about the apex half the
    // face width either side of M; its tip's toe and heel edges chamfered by `relief`.
    let (g, n) = ([pitch.sin(), pitch.cos()], [pitch.cos(), -pitch.sin()]);
    let at = |s: f64, off: f64| {
        let along = (s * s - off * off).sqrt();
        [along * g[0] + off * n[0], along * g[1] + off * n[1]]
    };
    let ang = |p: [f64; 2]| p[1].atan2(p[0]);
    let line = |a: [f64; 2], b: [f64; 2]| Seg::Line { a, b };
    let arc = |radius: f64, a: [f64; 2], b: [f64; 2]| Seg::Arc {
        center: [0.0, 0.0],
        radius,
        start: ang(a),
        sweep: ang(b) - ang(a),
    };
    let (s0, s1) = (cone - width / 2.0, cone + width / 2.0);
    let addendum = l.addendum;
    let (tb, hb, hf, tf) = (
        at(s0, -back),
        at(s1, -back),
        at(s1, addendum),
        at(s0, addendum),
    );
    let outline = if relief > 0.0 {
        // Each chamfer from `relief` down the sphere to `relief` along the tip.
        let face_dir = {
            let v = [tf[0] - hf[0], tf[1] - hf[1]];
            let len = v[0].hypot(v[1]);
            [v[0] / len, v[1] / len]
        };
        let hf_in = [hf[0] + relief * face_dir[0], hf[1] + relief * face_dir[1]];
        let tf_in = [tf[0] - relief * face_dir[0], tf[1] - relief * face_dir[1]];
        let down = |p: [f64; 2], s: f64, toward: [f64; 2]| {
            let a = ang(p) + (ang(toward) - ang(p)).signum() * relief / s;
            [s * a.cos(), s * a.sin()]
        };
        let (hf_down, tf_down) = (down(hf, s1, hb), down(tf, s0, tb));
        vec![
            line(tb, hb),
            arc(s1, hb, hf_down),
            line(hf_down, hf_in),
            line(hf_in, tf_in),
            line(tf_in, tf_down),
            arc(s0, tf_down, tb),
        ]
    } else {
        vec![line(tb, hb), arc(s1, hb, hf), line(hf, tf), arc(s0, tf, tb)]
    };
    let blank = Revolved {
        frame: frame(apex, axis, l.m),
        region: Region2 {
            outer: outline,
            holes: Vec::new(),
        },
        turn: None,
    };
    // The crown's tool about the cutter's axis, in (radius, height over P).
    let polygon = |pts: &[[f64; 2]]| Region2 {
        outer: (0..pts.len())
            .map(|i| line(pts[i], pts[(i + 1) % pts.len()]))
            .collect(),
        holes: Vec::new(),
    };
    let z = [0.0, 0.0, 1.0];
    let about_cutter = frame(l.cutter, z, add(l.cutter, [1.0, 0.0, 0.0]));
    let (ri, ro, ti, to) = (l.inner_radius, l.outer_radius, l.inner_tan, l.outer_tan);
    let (gi, go) = (grow * (1.0 + ti * ti).sqrt(), grow * (1.0 + to * to).sqrt());
    let (ded, base) = (l.dedendum, l.base);
    let tool = if gear {
        // The space: outside the outer blades' cone and inside the inner blades' a crown
        // pitch round, from a dedendum under P to the tooth's base over it.
        let reach = norm(l.cutter) + 1.1 * r + d.module;
        vec![
            Revolved {
                frame: about_cutter,
                region: polygon(&[
                    [ro + ded * to - go, -ded],
                    [reach, -ded],
                    [reach, base],
                    [ro - base * to - go, base],
                ]),
                turn: None,
            },
            Revolved {
                frame: about_cutter,
                region: polygon(&[
                    [0.0, -ded],
                    [ri - ded * ti + gi, -ded],
                    [ri + base * ti + gi, base],
                    [0.0, base],
                ]),
                turn: Some(([0.0; 3], z, -2.0 * PI / l.crown_teeth)),
            },
        ]
    } else {
        // The tooth: outside the inner blades' cone and inside the outer blades', from its
        // base under P to its tip a dedendum over it.
        vec![Revolved {
            frame: about_cutter,
            region: polygon(&[
                [ri - base * ti - gi, -base],
                [ro + base * to + go, -base],
                [ro - ded * to + go, ded],
                [ri + ded * ti - gi, ded],
            ]),
            turn: None,
        }]
    };
    // The crown turns about its axis; seen from the member, the member turns back at the
    // crown's teeth over its own (the gear the other way about its axis, which points away
    // from the pinion's side of P).
    let k = l.crown_teeth / teeth;
    let member_turn = if gear { k * ROLL } else { -k * ROLL };
    Generated {
        blank,
        tool,
        turns: [
            ([0.0; 3], z, -ROLL, ROLL),
            (apex, axis, -member_turn, member_turn),
        ],
        copies: teeth.round() as usize,
    }
}

/// `a x = b` by Cramer's rule.
fn solve3(a: [[f64; 3]; 3], b: [f64; 3]) -> Option<[f64; 3]> {
    let det = |m: [[f64; 3]; 3]| dot(m[0], cross(m[1], m[2]));
    let d = det(a);
    if d.abs() <= 1e-300 || d.is_nan() {
        return None;
    }
    let mut out = [0.0; 3];
    for (j, o) in out.iter_mut().enumerate() {
        let mut m = a;
        for i in 0..3 {
            m[i][j] = b[i];
        }
        *o = det(m) / d;
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `hypoid.sv`'s pair: 24 and 48 teeth, 2 mm at M, shafts square 25 mm apart, 25° spiral,
    /// its cutter and its pressure shift.
    pub(crate) fn sample() -> Design {
        Design {
            pinion_teeth: 24.0,
            gear_teeth: 48.0,
            module: 2.0,
            shaft_angle: PI / 2.0,
            offset: 25.0,
            spiral: 25f64.to_radians(),
            cutter_radius: 75.6122,
            pressure: 20f64.to_radians(),
            pressure_shift: 8.854_877_139_886_24_f64.to_radians(),
        }
    }

    /// Against the layout solved independently (numpy, the same constraints): ε, |AM|, γ; and
    /// `hypoid.sv`'s own check, |MV| cos(β + ε) = R cos β.
    #[test]
    fn the_layout_of_hypoid_sv() {
        let l = layout(&sample()).unwrap();
        for (got, want) in [
            (l.offset_angle, 0.438_370_115_148_009_33),
            (l.pinion_cone, 82.248_935_991_921_27),
            (l.pinion_pitch, 0.425_115_524_052_311_57),
        ] {
            assert!((got - want).abs() < 1e-9 * want, "{got} vs {want}");
        }
        let (r, beta) = (l.mean_cone, sample().spiral);
        let mv = l.pinion_radius() / l.gear_pitch.cos();
        assert!((mv * (beta + l.offset_angle).cos() - r * beta.cos()).abs() < 1e-9);
        // The axes: at right angles, 25 mm apart.
        let across = cross(l.pinion_axis, l.gear_axis);
        assert!(dot(l.gear_axis, l.pinion_axis).abs() < 1e-12);
        assert!((dot(l.pinion_apex, across) / norm(across) - 25.0).abs() < 1e-9);
        assert!((l.inner_radius - 74.181_849_673_761_22).abs() < 1e-9);
        assert!((l.outer_radius - 77.028_949_089_938_35).abs() < 1e-9);
    }

    /// With no offset the pinion's apex is the gear's and the pair a bevel pair: the pinion's
    /// pitch angle the gear's complement.
    #[test]
    fn no_offset_is_a_bevel_pair() {
        let l = layout(&Design {
            offset: 0.0,
            ..sample()
        })
        .unwrap();
        assert!(norm(l.pinion_apex) < 1e-9, "{:?}", l.pinion_apex);
        assert!((l.pinion_pitch + l.gear_pitch - PI / 2.0).abs() < 1e-9);
    }
}
